# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">AKIL VE İNANÇ İLİŞKİSİNE YÖNELİK FELSEFİ YAKLAŞIMLAR</text>\n  <rect x="20" y="48" width="205" height="172" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="122" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. FİDEİZM (İnanççılık)</text>\n  <rect x="32" y="82" width="181" height="124" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1"/>\n  <text x="122" y="102" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Tertullianus · Kierkegaard</text>\n  <text x="122" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• \'Akıl dışı olduğu için</text>\n  <text x="122" y="138" text-anchor="middle" font-size="9.5" fill="#334155">inanıyorum\' (Tertullianus).</text>\n  <text x="122" y="158" text-anchor="middle" font-size="9.5" fill="#334155">• Akıl sınırlıdır, iman alanına</text>\n  <text x="122" y="174" text-anchor="middle" font-size="9.5" fill="#334155">müdahale edemez.</text>\n  <text x="122" y="194" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#991b1b">Sonuç: Akıl-İnanç Uzlaşmazlığı</text>\n  <rect x="247" y="48" width="206" height="172" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. HRİSTİYAN UZLAŞIMI</text>\n  <rect x="259" y="82" width="182" height="124" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1"/>\n  <text x="350" y="102" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Augustinus · Anselmus · Thomas</text>\n  <text x="350" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• \'Anlamak için inanıyorum\'</text>\n  <text x="350" y="138" text-anchor="middle" font-size="9.5" fill="#334155">(Augustinus ve Anselmus).</text>\n  <text x="350" y="158" text-anchor="middle" font-size="9.5" fill="#334155">• \'İnanmak için anlıyorum\'</text>\n  <text x="350" y="174" text-anchor="middle" font-size="9.5" fill="#334155">(Aquinolu Thomas).</text>\n  <text x="350" y="194" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e40af">Sonuç: Akıl İnanç Hizmetindedir</text>\n  <rect x="475" y="48" width="205" height="172" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="577" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. İSLAM FELSEFESİ UYUMU</text>\n  <rect x="487" y="82" width="181" height="124" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1"/>\n  <text x="577" y="102" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Kindî · Fârâbî · İbn Rüşd</text>\n  <text x="577" y="122" text-anchor="middle" font-size="9.5" fill="#334155">• Akıl da vahiy de Allah</text>\n  <text x="577" y="138" text-anchor="middle" font-size="9.5" fill="#334155">vergisi olduğundan çelişmez.</text>\n  <text x="577" y="158" text-anchor="middle" font-size="9.5" fill="#334155">• \'Hakikat hakikate ters düşmez;\'</text>\n  <text x="577" y="174" text-anchor="middle" font-size="9.5" fill="#334155">felsefe dinin süt kardeşidir.</text>\n  <text x="577" y="194" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#166534">Sonuç: Tam Hakikat Birliği</text>\n</svg>', '<svg viewBox="0 0 700 245" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="245" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TANRI\'NIN VARLIĞINA İLİŞKİN KLASİK FELSEFİ KANITLAR</text>\n  <rect x="20" y="44" width="320" height="88" rx="8" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="180" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#3730a3">1. ONTOLOJİK KANIT (A Priori)</text>\n  <text x="180" y="84" text-anchor="middle" font-size="9.5" fill="#334155">• \'Kendisinden daha yetkini düşünülemeyen varlık\'</text>\n  <text x="180" y="100" text-anchor="middle" font-size="9.5" fill="#334155">kavramından doğrudan gerçek varlığa ulaşır.</text>\n  <text x="180" y="118" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#4338ca">Temsilciler: Anselmus, Descartes, İbn Sînâ</text>\n  <rect x="360" y="44" width="320" height="88" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="64" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">2. KOZMOLOJİK KANIT (İlk Neden)</text>\n  <text x="520" y="84" text-anchor="middle" font-size="9.5" fill="#334155">• Nedenler zinciri sonsuza dek gidemez (teselsül).</text>\n  <text x="520" y="100" text-anchor="middle" font-size="9.5" fill="#334155">• Hudûs (sonradan olma) ve İmkân (Vâcibü\'l-Vücûd)</text>\n  <text x="520" y="118" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">Temsilciler: Aristoteles, Kindî, Gazzâlî, Thomas</text>\n  <rect x="20" y="144" width="320" height="88" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="180" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">3. TELEOLOJİK KANIT (Düzen ve Amaç)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="9.5" fill="#334155">• Evrendeki hassas düzen, ölçü ve gayelilik</text>\n  <text x="180" y="200" text-anchor="middle" font-size="9.5" fill="#334155">bilinçli bir tasarımcıyı (Yaratıcı) gösterir.</text>\n  <text x="180" y="218" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Temsilciler: İbn Rüşd (İnayet/İhtirâ), W. Paley</text>\n  <rect x="360" y="144" width="320" height="88" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="520" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. AHLAKİ KANIT (Pratik Akıl)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="9.5" fill="#334155">• Evrensel ahlak yasası ve \'en yüksek iyi\'nin</text>\n  <text x="520" y="200" text-anchor="middle" font-size="9.5" fill="#334155">(erdem + mutluluk) gerçekleşmesi Tanrı\'yı gerektirir.</text>\n  <text x="520" y="218" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#7e22ce">Temsilci: Immanuel Kant (Pratik Aklın Postulatı)</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM DÜŞÜNCESİNDE AKIL - VAHİY (FELSEFE - DİN) TARTIŞMASI</text>\n  <rect x="20" y="45" width="210" height="162" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">FÂRÂBÎ VE İBN SÎNÂ</text>\n  <text x="125" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Filozof ve peygamber bilgisini</text>\n  <text x="125" y="106" text-anchor="middle" font-size="9.5" fill="#334155">Faal Akıl\'dan alır.</text>\n  <text x="125" y="126" text-anchor="middle" font-size="9.5" fill="#334155">• Felsefe burhanla (kavramla),</text>\n  <text x="125" y="142" text-anchor="middle" font-size="9.5" fill="#334155">din ise sembollerle anlatır.</text>\n  <text x="125" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">Hakikat tektir, ifade farklıdır.</text>\n  <rect x="245" y="45" width="210" height="162" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">İMAM GAZZÂLÎ</text>\n  <text x="350" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Eser: Tehâfütü\'l-Felâsife</text>\n  <text x="350" y="108" text-anchor="middle" font-size="9.5" fill="#334155">• Mantık ve bilimi kabul eder;</text>\n  <text x="350" y="124" text-anchor="middle" font-size="9.5" fill="#334155">metafizikte aklı sınırlı bulur.</text>\n  <text x="350" y="144" text-anchor="middle" font-size="9.5" fill="#334155">• Hakikate ulaşmada vahiy ve</text>\n  <text x="350" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">kalp gözünü (sezgi) üstün tutar.</text>\n  <rect x="470" y="45" width="210" height="162" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">İBN RÜŞD</text>\n  <text x="575" y="90" text-anchor="middle" font-size="9.5" fill="#334155">• Eser: Faslü\'l-Makâl</text>\n  <text x="575" y="108" text-anchor="middle" font-size="9.5" fill="#334155">• \'Hakikat hakikate ters düşmez;\'</text>\n  <text x="575" y="124" text-anchor="middle" font-size="9.5" fill="#334155">felsefe dinin süt kardeşidir.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="9.5" fill="#334155">• Görünürde çelişki varsa ayet</text>\n  <text x="575" y="166" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">akla göre te\'vil (yorum) edilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
